let currentLanguage = readSavedLanguage();

function readSavedLanguage() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return SUPPORTED.includes(saved) ? saved : "en";
  } catch (_) {
    return "en";
  }
}

export function getLanguage() { return currentLanguage; }

export function setLanguage(language, { persist = true } = {}) {
  currentLanguage = SUPPORTED.includes(language) ? language : "en";
  if (persist) {
    try { localStorage.setItem(STORAGE_KEY, currentLanguage); } catch (_) { /* Storage may be unavailable in private browsing. */ }
  }
  document.documentElement.lang = currentLanguage;
  return currentLanguage;
}

export function t(key, variables = {}) {
  const template = messages[currentLanguage][key] ?? messages.en[key] ?? key;
  return String(template).replace(/\{([\w]+)\}/g, (_, name) => String(variables[name] ?? ""));
}

export function translateDocument(root = document) {
  document.title = t("meta.title");
  const description = document.querySelector("meta[name=description]");
  if (description) description.content = t("meta.description");
  root.querySelectorAll("[data-i18n]").forEach(element => {
    // Translate text-only nodes. Never replace an element's contents when it
    // contains icons, SVGs, or other child markup.
    if (element.childElementCount > 0 || element.matches("svg,[data-icon],.nav-icon,.stat-icon,.upgrade-spark,.profile-dots,.icon-button,.calendar-step,.close-button,.task-check,.focus-selected-mark,.analytics-empty-mark")) return;
    element.textContent = t(element.dataset.i18n);
  });
  root.querySelectorAll("[data-i18n-placeholder]").forEach(element => { element.placeholder = t(element.dataset.i18nPlaceholder); });
  root.querySelectorAll("[data-i18n-aria]").forEach(element => { element.setAttribute("aria-label", t(element.dataset.i18nAria)); });
}

export function hasSavedLanguage() {
  try { return localStorage.getItem(STORAGE_KEY) !== null; } catch (_) { return false; }
}

export function supportedLanguages() { return SUPPORTED.slice(); }









